diff --git a/overrides/app/components/item-variant/item-image.tsx b/overrides/app/components/item-variant/item-image.tsx
index 1b109a80..4d7f80c5 100644
--- a/overrides/app/components/item-variant/item-image.tsx
+++ b/overrides/app/components/item-variant/item-image.tsx
@@ -8,20 +8,36 @@
 /*
  * Copy-first port of node_modules/@salesforce/retail-react-app/app/components/item-variant/item-image.jsx
  * (retail-react-app 10.0.0), converted to TypeScript per AGENTS.md's copy-first rule (SFCC-270,
- * plan step 2.1). Zero functional diff beyond the TypeScript annotations below and a temporary
- * `[overrides]` console.log marker (verified live, then removed). The
- * `<Box width="84px" backgroundColor="gray.100" {...props}>`
- * defaults-then-spread prop order is preserved exactly, unchanged from base — that ordering is
- * what lets a caller-supplied width (e.g. product-item/index.tsx's `width={['88px', '136px']}`)
- * override the default.
+ * plan step 2.1). Zero functional diff at that step beyond the TypeScript annotations and a
+ * temporary `[overrides]` console.log marker (verified live, then removed).
  *
  * `useItemVariant` is already imported via the relative `'.'` in the base file — unchanged here.
+ *
+ * SFCC-270 (plan step 2.2): restyled to the Figma cart-item spec. The outer Box's own literal
+ * `width="84px" backgroundColor="gray.100"` defaults are gone, replaced by item-variant.css.ts's
+ * `image` part via `__css` — kept as `__css`, not `sx`, specifically so a caller-supplied
+ * `width`/`mr` (e.g. order-summary/index.jsx's base, not-yet-overridden
+ * `<CartItemVariantImage width="80px" mr={2} />`) still wins; see that recipe's own docblock for
+ * why. `{...props}` stays spread last, same defaults-then-spread order as before, still what
+ * lets that caller-supplied width win. `ratio`'s default changed from `1` to the Figma-confirmed
+ * 288/432 cart-item image ratio; the inner <Image> now also carries the `img` part's responsive
+ * objectFit + mix-blend-multiply. Badge styling (Sale/Unavailable) is untouched — no Figma value
+ * was given for it at this step.
  */
 import React from 'react';
-import { AspectRatio, Box, Badge, Image } from '@salesforce/retail-react-app/app/components/shared/ui';
+import {
+  AspectRatio,
+  Box,
+  Badge,
+  Image,
+  useMultiStyleConfig,
+} from '@salesforce/retail-react-app/app/components/shared/ui';
 import { useItemVariant } from '.';
 import { FormattedMessage } from 'react-intl';
 import { findImageGroupBy } from '@salesforce/retail-react-app/app/utils/image-groups-utils';
+// Recipe key — single source in item-variant.css.ts (SFCC-270 round 2 rework), no longer
+// redeclared per file.
+import { ZIMM_CART_ITEM_VARIANT_RECIPE } from './item-variant.css';

 // See index.tsx's own note on why this is `any` rather than a structural type.
 type SfccVariant = any;
@@ -31,6 +47,13 @@ type ItemImageProps = {
   ratio?: number;
 } & Record<string, any>;

+// Figma "Image" spec, product-item card (SFCC-270): aspect ratio 288/432, which reduces to 2/3
+// exactly. Matches the design record's own 132x198 desktop pair exactly (132 * 432/288 = 198);
+// against the 67x100 mobile pair it lands at 100.5 — half a pixel over the stated 100, the same
+// class of Figma-rounding gap zimmDrawer.css.ts's WIDTH_XLARGE note already documents for a
+// different value, not something introduced here.
+const CART_ITEM_IMAGE_RATIO = 288 / 432;
+
 /**
  * In the context of a cart product item variant, this component renders the item's
  * main image.
