/**
 * SFCC-270 (plan step 2.2). Covers:
 *   - item-image.tsx: a caller-supplied `width`/`mr` must win over the Zimmermann default
 *     (item-variant.css.ts's `image` part) — this is exactly what order-summary/index.jsx's
 *     (base, not-yet-overridden) `<CartItemVariantImage width="80px" mr={2} />` depends on.
 *   - item-name.tsx: a caller-supplied `color` must win over the Zimmermann default — the bug
 *     fix at this step (base had the spread BEFORE the explicit `color`, silently discarding
 *     any caller value).
 *   - item-attributes.tsx (round 2 rework): the pre-existing per-key rendering path — used
 *     unmodified today by order-summary, wishlist/checkout partials, account/order-detail, and
 *     the confirmation page — still renders correctly now that it sits behind this build's new
 *     `!combineAttributeValues &&` guard.
 *   - item-price.tsx (round 2 rework, should-fix): the `isDesktop`-gated PricePerItem
 *     positioning, the `isOnSale`-driven stack spacing, and the `price` recipe's textStyle.
 *
 * `useMultiSite` is mocked, not provided via a real MultiSiteProvider: item-name.tsx's <Link>
 * calls it internally, and its real dependency chain (`@salesforce/retail-react-app/app/
 * contexts`) fails to parse under Vitest's Vite transform — same mock, same reasoning, as
 * header/rightBar/index.test.tsx's own `vi.mock('.../use-multi-site', ...)`.
 *
 * item-attributes.tsx/item-price.tsx pull in several more hooks that need the same treatment,
 * all following that identical established pattern (mock the smallest surface, per
 * .claude/rules/testing.md): `useCurrency` (full replacement — this file's render tree never
 * needs the real `useDerivedProduct` also exported from that barrel, unlike
 * product-item/index.test.tsx, so no `vi.importActual` juggling is needed here), a real-network
 * `useCurrentBasket`, `PromoPopover` (imports the base icons barrel, throws under Vitest per
 * testing.md's documented ZimmIcon gap), and `usePromotions`/`useProducts`/`useProduct` from
 * `@salesforce/commerce-sdk-react`. `useBreakpointValue` is mocked directly (from `@chakra-ui/react`,
 * which `shared/ui`'s own `useBreakpointValue` module just re-exports) so item-price.tsx's
 * `isDesktop` resolves to an exact, per-test value — the same pattern
 * zimmSizeSelector/index.test.tsx already establishes, rather than fighting Chakra's internal
 * breakpoint-matching media queries via a `window.matchMedia` mock.
 */
import React from 'react';
import { describe, test, expect, vi, beforeEach } from 'vitest';
import { render, screen } from '@testing-library/react';
import { ChakraProvider, useBreakpointValue } from '@chakra-ui/react';
import { IntlProvider } from 'react-intl';
import { MemoryRouter } from 'react-router-dom';
import theme from 'app/theme';
import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
import ItemVariantProvider from '.';
import CartItemVariantImage from './item-image';
import CartItemVariantName from './item-name';
import CartItemVariantAttributes from './item-attributes';
import CartItemVariantPrice from './item-price';

vi.mock('@salesforce/retail-react-app/app/hooks/use-multi-site', () => ({
  default: vi.fn(),
}));

vi.mock('@salesforce/retail-react-app/app/hooks', () => ({
  useCurrency: () => ({ currency: 'AUD', setCurrency: vi.fn() }),
}));

vi.mock('@salesforce/retail-react-app/app/hooks/use-current-basket', () => ({
  useCurrentBasket: () => ({ data: undefined }),
}));

vi.mock('@salesforce/retail-react-app/app/components/promo-popover', () => ({
  default: ({ children }: { children?: React.ReactNode }) => <>{children}</>,
}));

vi.mock('@salesforce/commerce-sdk-react', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@salesforce/commerce-sdk-react')>();
  return {
    ...actual,
    usePromotions: () => ({ data: undefined }),
    useProducts: () => ({ data: undefined, isLoading: false }),
    useProduct: () => ({ data: undefined, isLoading: false }),
  };
});

vi.mock('@chakra-ui/react', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@chakra-ui/react')>();
  return {
    ...actual,
    useBreakpointValue: vi.fn(),
  };
});

const mockUseMultiSite = vi.mocked(useMultiSite);
const mockUseBreakpointValue = vi.mocked(useBreakpointValue);

// ChakraProvider with this project's own theme is required, not optional here — without it,
// `textStyle="productNames"` resolves against Chakra's default (empty) textStyles, and
// `useBreakpointValue` (item-price.tsx, exercised transitively were this file to render it)
// throws outright reading `theme.breakpoints` off an undefined theme. Same setup zimmButton's
// own test uses.
const renderWithProviders = (ui: React.ReactElement) =>
  render(
    <ChakraProvider theme={theme}>
      <MemoryRouter>
        <IntlProvider locale="en-AU" defaultLocale="en-AU">
          {ui}
        </IntlProvider>
      </MemoryRouter>
    </ChakraProvider>,
  );

const baseVariant = {
  id: 'variant-1',
  productName: 'Lilac Sand Dress',
  imageGroups: [
    {
      viewType: 'small',
      images: [{ alt: 'Lilac Sand Dress', link: 'https://example.invalid/lilac-sand.jpg' }],
    },
  ],
};

describe('item-variant', () => {
  beforeEach(() => {
    mockUseMultiSite.mockReturnValue({
      site: { id: 'ZimmermannAU' },
      buildUrl: (path: string) => path,
    });
  });

  describe('CartItemVariantImage (item-image) — defaults-then-spread', () => {
    test('a caller-supplied width wins over the Zimmermann default', () => {
      const { container } = renderWithProviders(
        <ItemVariantProvider variant={baseVariant}>
          <CartItemVariantImage width="321px" />
        </ItemVariantProvider>,
      );
      const box = container.firstElementChild as HTMLElement;
      expect(box).toHaveStyle({ width: '321px' });
    });

    test('a caller-supplied mr is applied (the exact regression that would break order-summary)', () => {
      const { container } = renderWithProviders(
        <ItemVariantProvider variant={baseVariant}>
          <CartItemVariantImage mr="37px" />
        </ItemVariantProvider>,
      );
      const box = container.firstElementChild as HTMLElement;
      expect(box).toHaveStyle({ marginRight: '37px' });
    });
  });

  describe('CartItemVariantName (item-name) — spread-order bug fix', () => {
    test('a caller-supplied color wins over the Zimmermann default', () => {
      renderWithProviders(
        <ItemVariantProvider variant={baseVariant}>
          <CartItemVariantName color="rgb(255, 0, 0)" />
        </ItemVariantProvider>,
      );
      const link = screen.getByRole('link', { name: 'Lilac Sand Dress' });
      expect(link).toHaveStyle({ color: 'rgb(255, 0, 0)' });
    });

    test('renders uppercase via textStyle="productNames" (text-transform, not literal casing)', () => {
      renderWithProviders(
        <ItemVariantProvider variant={baseVariant}>
          <CartItemVariantName />
        </ItemVariantProvider>,
      );
      // Asserted on the <Heading> textStyle is actually applied to, not the nested <Link> —
      // text-transform is CSS-inherited from parent to child, and jsdom's getComputedStyle does
      // not reliably resolve inherited (as opposed to directly-applied) declarations.
      const heading = screen.getByRole('heading', { level: 2 });
      expect(heading).toHaveStyle({ textTransform: 'uppercase' });
    });
  });

  describe('CartItemVariantAttributes (item-attributes) — combineAttributeValues default (per-key) path', () => {
    // Shape matches getDisplayVariationValues's own real contract (product-utils.js) — the real,
    // unmocked utility is exercised here, not stubbed, since this test is specifically about the
    // per-key rendering path's own contract.
    const attributesVariant = {
      id: 'variant-1',
      productName: 'Lilac Sand Dress',
      variationAttributes: [
        { id: 'color', name: 'Colour', values: [{ value: 'JJ5FUXX', name: 'Lilac Sand', orderable: true }] },
        { id: 'size', name: 'Size', values: [{ value: 'ONESIZE', name: 'One Size', orderable: true }] },
      ],
      variationValues: { color: 'JJ5FUXX', size: 'ONESIZE' },
    };

    // Round 2 rework (must-fix 2): this branch has six real, unmodified callers today
    // (order-summary, wishlist partials, checkout partials, account/order-detail, the
    // confirmation page) and none of them pass combineAttributeValues — this proves this
    // build's new `!combineAttributeValues &&` guard still renders their per-key output.
    test('renders one Text per variation-value key, with labels, when combineAttributeValues is omitted', () => {
      renderWithProviders(
        <ItemVariantProvider variant={attributesVariant}>
          <CartItemVariantAttributes />
        </ItemVariantProvider>,
      );

      expect(screen.getByText('Colour: Lilac Sand')).toBeInTheDocument();
      expect(screen.getByText('Size: One Size')).toBeInTheDocument();
      // Not the combined-string shape — proves the per-key branch rendered, not the combined one.
      expect(screen.queryByText('Lilac Sand, One Size')).not.toBeInTheDocument();
    });

    test('hideAttributeLabels still renders per-key (one Text per key), just without the "Key: " prefix', () => {
      renderWithProviders(
        <ItemVariantProvider variant={attributesVariant}>
          <CartItemVariantAttributes hideAttributeLabels />
        </ItemVariantProvider>,
      );

      expect(screen.getByText('Lilac Sand')).toBeInTheDocument();
      expect(screen.getByText('One Size')).toBeInTheDocument();
      expect(screen.queryByText('Colour: Lilac Sand')).not.toBeInTheDocument();
    });
  });

  describe('CartItemVariantPrice (item-price) — rendering logic', () => {
    const priceVariant = (overrides: Record<string, unknown> = {}) => ({
      id: 'variant-1',
      itemId: 'item-1',
      name: 'Lilac Sand Dress',
      price: 200,
      priceAfterItemDiscount: 200,
      pricePerUnit: 100,
      quantity: 2,
      ...overrides,
    });

    test('isDesktop-gated positioning: PricePerItem renders before the main price on mobile, after it on desktop', () => {
      mockUseBreakpointValue.mockReturnValue(false);
      const mobile = renderWithProviders(
        <ItemVariantProvider variant={priceVariant()}>
          <CartItemVariantPrice currency="AUD" />
        </ItemVariantProvider>,
      );
      const perItemMobile = screen.getByText('$100.00ea');
      const mainPriceMobile = screen.getByText('$200.00');
      // Node.DOCUMENT_POSITION_FOLLOWING: mainPrice comes AFTER perItem in document order.
      expect(perItemMobile.compareDocumentPosition(mainPriceMobile) & Node.DOCUMENT_POSITION_FOLLOWING).toBeTruthy();
      mobile.unmount();

      mockUseBreakpointValue.mockReturnValue(true);
      renderWithProviders(
        <ItemVariantProvider variant={priceVariant()}>
          <CartItemVariantPrice currency="AUD" />
        </ItemVariantProvider>,
      );
      const perItemDesktop = screen.getByText('$100.00ea');
      const mainPriceDesktop = screen.getByText('$200.00');
      // Reversed: perItem now comes AFTER mainPrice.
      expect(
        mainPriceDesktop.compareDocumentPosition(perItemDesktop) & Node.DOCUMENT_POSITION_FOLLOWING,
      ).toBeTruthy();
    });

    test('isOnSale collapses the price Stack spacing to 0, otherwise theme.space[1] (0.25rem)', () => {
      mockUseBreakpointValue.mockReturnValue(false);

      const notOnSale = renderWithProviders(
        <ItemVariantProvider variant={priceVariant({ price: 200, priceAfterItemDiscount: 200, quantity: 1 })}>
          <CartItemVariantPrice currency="AUD" />
        </ItemVariantProvider>,
      );
      const notOnSaleStack = notOnSale.container.firstElementChild as HTMLElement;
      // Chakra/emotion emits a CSS custom-property reference for a registered space-scale
      // value, not the literal rem — confirmed by reading the actual rendered style, not assumed.
      expect(notOnSaleStack).toHaveStyle({ gap: 'var(--chakra-space-1)' });
      notOnSale.unmount();

      const onSale = renderWithProviders(
        <ItemVariantProvider variant={priceVariant({ price: 250, priceAfterItemDiscount: 200, quantity: 1 })}>
          <CartItemVariantPrice currency="AUD" />
        </ItemVariantProvider>,
      );
      const onSaleStack = onSale.container.firstElementChild as HTMLElement;
      // Unlike space[1] above, Chakra's own default scale has no `0` key at all (confirmed by
      // reading @chakra-ui/theme's spacing chunk) — so `spacing={0}` isn't a scale lookup, it's
      // the literal value passed straight through, rendering as a plain `0px`, not a CSS var.
      expect(onSaleStack).toHaveStyle({ gap: '0px' });
    });

    test('applies the price recipe (textStyle) directly to its own Stack', () => {
      mockUseBreakpointValue.mockReturnValue(false);
      const { container } = renderWithProviders(
        <ItemVariantProvider variant={priceVariant({ quantity: 1 })}>
          <CartItemVariantPrice currency="AUD" />
        </ItemVariantProvider>,
      );
      const stack = container.firstElementChild as HTMLElement;
      // theme/foundation/typography.ts's `price` textStyle: fontSize '2xs' (0.875rem), fontWeight
      // medium (500) — verified against the real registered scale, not assumed.
      expect(stack).toHaveStyle({ fontSize: '0.875rem', fontWeight: '500' });
    });
  });
});

