1	/**
2	 * SFCC-270 (plan step 2.2). Covers this build's own pass criteria for product-item/index.tsx:
3	 * image renders with an alt, name renders uppercase, price renders, and the colour+size string
4	 * renders as one combined text node (not two separate ones).
5	 *
6	 * Mocks the smallest surface a rendered ProductItem calls transitively (testing.md's own
7	 * guidance), rather than standing up the full commerce-hook dependency chain a real render
8	 * would need (CurrencyContext, CommerceApiProvider, useVariant/useVariationParams/
9	 * useSelectedStore via the real useDerivedProduct, react-intl's IntlProvider via useIntl) —
10	 * this test is about ProductItem's OWN render contract, not re-proving those hooks' own
11	 * correctness, which is out of this file's scope. `use-multi-site` is mocked for the same
12	 * parse-failure-under-Vitest reason item-variant/index.test.tsx's own docblock explains.
13	 */
14	import React from 'react';
15	import { describe, test, expect, vi, beforeEach } from 'vitest';
16	import { render, screen } from '@testing-library/react';
17	import { ChakraProvider } from '@chakra-ui/react';
18	import { IntlProvider } from 'react-intl';
19	import { MemoryRouter } from 'react-router-dom';
20	import theme from 'app/theme';
21	import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
22	import ProductItem from '.';
23	
24	vi.mock('@salesforce/retail-react-app/app/hooks/use-multi-site', () => ({
25	  default: vi.fn(),
26	}));
27	
28	vi.mock('@salesforce/retail-react-app/app/hooks', () => ({
29	  useCurrency: () => ({ currency: 'AUD', setCurrency: vi.fn() }),
30	  useDerivedProduct: () => ({
31	    stepQuantity: 1,
32	    showInventoryMessage: false,
33	    inventoryMessage: '',
34	    quantity: 1,
35	    setQuantity: vi.fn(),
36	  }),
37	}));
38	
39	vi.mock('@salesforce/retail-react-app/app/hooks/use-current-basket', () => ({
40	  useCurrentBasket: () => ({ data: undefined }),
41	}));
42	
43	// item-attributes.tsx imports PromoPopover unconditionally, which imports the base SFCC icons
44	// barrel — that barrel has a top-level side effect (`AmexSymbol.viewBox = ...`) that throws
45	// under Vitest (SVG imports resolve to raw path strings here, not components). Same root cause,
46	// same fix shape, as testing.md's documented ZimmIcon workaround, just via a different import
47	// path (PromoPopover, not ZimmIcon) — not fixable from this test file beyond mocking it away.
48	vi.mock('@salesforce/retail-react-app/app/components/promo-popover', () => ({
49	  default: ({ children }: { children?: React.ReactNode }) => <>{children}</>,
50	}));
51	
52	vi.mock('@salesforce/commerce-sdk-react', async (importOriginal) => {
53	  const actual = await importOriginal<typeof import('@salesforce/commerce-sdk-react')>();
54	  return {
55	    ...actual,
56	    usePromotions: () => ({ data: undefined }),
57	    useProducts: () => ({ data: undefined, isLoading: false }),
58	    useProduct: () => ({ data: undefined, isLoading: false }),
59	  };
60	});
61	
62	// Bypasses the real utility's own variationAttributes/variationValues matching logic — this
63	// test is about ProductItem's own render contract (does a combined value render as one node),
64	// not about re-proving getDisplayVariationValues' own correctness. See
65	// item-variant/item-attributes.tsx's own SFCC-270 docblock for combineAttributeValues' contract.
66	vi.mock('@salesforce/retail-react-app/app/utils/product-utils', async (importOriginal) => {
67	  const actual = await importOriginal<typeof import('@salesforce/retail-react-app/app/utils/product-utils')>();
68	  return {
69	    ...actual,
70	    getDisplayVariationValues: () => ({ Colour: 'Lilac Sand', Size: 'One size' }),
71	  };
72	});
