91	const MOCK_LINE_ITEM = {
92	  itemId: 'a1b2c3d4e5f6a1b2c3d4e5f6',
93	  productId: '25595021M',
94	  id: '25595021M',
95	  productName: 'Lilac Sand Silk Midi Dress',
96	  name: 'Lilac Sand Silk Midi Dress',
97	  price: 495,
98	  priceAfterItemDiscount: 495,
99	  pricePerUnit: 495,
100	  quantity: 1,
101	  imageGroups: [
102	    {
103	      viewType: 'small',
104	      images: [{ alt: 'Lilac Sand Silk Midi Dress', link: 'https://example.invalid/lilac-sand.jpg' }],
105	    },
106	  ],
107	};
