109	describe('ProductItem', () => {
110	  // jsdom has no matchMedia implementation, and item-price.tsx's `isDesktop` uses
111	  // useBreakpointValue internally, which calls it — a per-file polyfill, not a change to the
112	  // frozen vitest.setup.ts (Tier 1). Same pattern and reasoning as drawer-menu/index.test.tsx's
113	  // own beforeEach.
114	  beforeEach(() => {
115	    Object.defineProperty(window, 'matchMedia', {
116	      writable: true,
117	      value: vi.fn().mockImplementation((query: string) => ({
118	        matches: false,
119	        media: query,
120	        onchange: null,
121	        addListener: vi.fn(),
122	        removeListener: vi.fn(),
123	        addEventListener: vi.fn(),
124	        removeEventListener: vi.fn(),
125	        dispatchEvent: vi.fn(),
126	      })),
127	    });
128	
129	    mockUseMultiSite.mockReturnValue({
130	      site: { id: 'ZimmermannAU' },
131	      buildUrl: (path: string) => path,
132	    });
133	  });
134	
135	  test('renders the image with an alt, the name uppercase, the price, and one combined colour+size node', () => {
136	    renderWithProviders(<ProductItem product={MOCK_LINE_ITEM} />);
137	
138	    // Image renders with an alt.
139	    expect(screen.getByAltText('Lilac Sand Silk Midi Dress')).toBeInTheDocument();
140	
141	    // Name renders uppercase (textStyle="productNames" sets text-transform, not literal casing —
142	    // the DOM text content itself stays as authored). Asserted on the <Heading> textStyle is
143	    // actually applied to, not the nested <Link> — see item-variant/index.test.tsx's own note
144	    // on why (text-transform is CSS-inherited, and jsdom's getComputedStyle does not reliably
145	    // resolve inherited declarations).
146	    expect(screen.getByRole('heading', { level: 2 })).toHaveStyle({ textTransform: 'uppercase' });
147	
148	    // Price renders — DisplayPrice/CurrentPrice formats $495.00 via react-intl; rendered twice
149	    // (mobile + desktop slots both exist in the DOM under jsdom, which does not evaluate CSS
150	    // media queries — see header/rightBar/index.test.tsx's own note on this exact behaviour).
151	    expect(screen.getAllByText('$495.00').length).toBeGreaterThan(0);
152	
153	    // The colour+size string renders as ONE text node containing both values — not two
154	    // separate nodes. An exact-string query only matches if both values live in the same node.
155	    expect(screen.getByText('Lilac Sand, One size')).toBeInTheDocument();
156	  });
157	
158	  // Round 2 rework, must-fix 4: the gift-card capability slot. Only the capability is asserted
159	  // here — not real gift-card detection, which this build still cannot do (see this component's
160	  // own docblock).
161	  test('hideStepperAndActions suppresses the stepper and every actions surface, and nothing throws', () => {
162	    expect(() =>
163	      renderWithProviders(
164	        <ProductItem
165	          product={MOCK_LINE_ITEM}
166	          primaryAction={<button type="button">Remove</button>}
167	          secondaryActions={<button type="button">Edit</button>}
168	          deliveryActions={<span>Ship to store</span>}
169	          hideStepperAndActions
170	        />,
171	      ),
172	    ).not.toThrow();
173	
174	    // Stepper: ProductQuantityPicker's own "Quantity:" label is the only source of this text in
175	    // this render tree (product-item/index.tsx never passes includeQuantity to
176	    // CartItemVariantAttributes), so its absence proves the stepper itself did not render.
177	    expect(screen.queryByText('Quantity:')).not.toBeInTheDocument();
178	
179	    // Actions: primaryAction/secondaryActions/deliveryActions all suppressed.
180	    expect(screen.queryByRole('button', { name: 'Remove' })).not.toBeInTheDocument();
181	    expect(screen.queryByRole('button', { name: 'Edit' })).not.toBeInTheDocument();
182	    expect(screen.queryByText('Ship to store')).not.toBeInTheDocument();
183	
184	    // The rest of the component is unaffected — image/name/price/attributes still render.
185	    expect(screen.getByAltText('Lilac Sand Silk Midi Dress')).toBeInTheDocument();
186	    expect(screen.getByText('Lilac Sand, One size')).toBeInTheDocument();
187	  });
188	
189	  test('every existing caller (hideStepperAndActions omitted) is unaffected — the stepper and actions still render', () => {
190	    renderWithProviders(
191	      <ProductItem
192	        product={MOCK_LINE_ITEM}
193	        primaryAction={<button type="button">Remove</button>}
194	        secondaryActions={<button type="button">Edit</button>}
195	        deliveryActions={<span>Ship to store</span>}
196	      />,
197	    );
198	
199	    expect(screen.getByText('Quantity:')).toBeInTheDocument();
200	    expect(screen.getAllByRole('button', { name: 'Remove' }).length).toBeGreaterThan(0);
201	    expect(screen.getByRole('button', { name: 'Edit' })).toBeInTheDocument();
202	    expect(screen.getAllByText('Ship to store').length).toBeGreaterThan(0);
203	  });
204	});
